      runAs: ACCOUNT,
      sandboxRuntimePaths: ["/usr/bin"],
      sandboxRuntimeRoots: ["/usr/bin"],
      corpusCustody: { storeRoot: "/usr/bin/synthetic-corpus-leak" },
      resources,
