    const base = { name: "failclosed", qualification: true, endpoint: "http://127.0.0.1:9/v1", model: "m", runAs: ACCOUNT, sandboxRuntimePaths: [], sandboxRuntimeRoots: ["/opt/nexus-qual"] };
