      [{ ...base, resources: undefined }, /enforced CPU, memory, process-count, and workspace-storage limits/],
      [{ ...base, resources: { ...resources, workspaceRoot: os.tmpdir() } }, /tmpfs/],
      [{ ...base, runAs: undefined, resources }, /runAs/],
